// Hand-maintained since the Firebase Auth swap — this file used to be
// regenerated by Lovable's Supabase integration tooling (localStorage-backed
// Supabase session). It now attaches Firebase ID tokens as the bearer token
// instead (Supabase Third-Party Auth verifies them directly), so it's no
// longer something that generator can produce; don't expect it to survive a
// future "Connect Supabase" regeneration untouched.
import { createClient } from '@supabase/supabase-js';
import { onIdTokenChanged } from 'firebase/auth';
import type { Database } from './types';
import { firebaseAuth } from '@/integrations/firebase/client';

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith('sb_publishable_') || value.startsWith('sb_secret_');
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== 'undefined' && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (isNewSupabaseApiKey(supabaseKey) && headers.get('Authorization') === `Bearer ${supabaseKey}`) {
      headers.delete('Authorization');
    }

    headers.set('apikey', supabaseKey);
    return fetch(input, { ...init, headers });
  };
}


function createSupabaseClient() {
  // Use import.meta.env for client-side (Vite build-time replacement)
  // Fall back to process.env for SSR (server-side rendering)
  const SUPABASE_URL =
    import.meta.env.NEXT_PUBLIC_SUPABASE_URL ||
    import.meta.env.VITE_SUPABASE_URL ||
    process.env.NEXT_PUBLIC_SUPABASE_URL ||
    process.env.SUPABASE_URL;
  const SUPABASE_PUBLISHABLE_KEY =
    import.meta.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ||
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ||
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ||
    process.env.SUPABASE_PUBLISHABLE_KEY;

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
      ...(!SUPABASE_PUBLISHABLE_KEY ? ['SUPABASE_PUBLISHABLE_KEY'] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Connect Supabase in Lovable Cloud.`;
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    global: {
      fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
    },
    auth: {
      // No local Supabase session anymore — Firebase owns sign-in/persistence.
      // Every Supabase request just carries the current Firebase ID token,
      // per Supabase's documented Third-Party Auth pattern; Postgres/Storage
      // verify it directly (confirmed live in the Phase 1 spike).
      persistSession: false,
      autoRefreshToken: false,
    },
    accessToken: async () => (await firebaseAuth.currentUser?.getIdToken()) ?? null,
  });
}

let _supabase: ReturnType<typeof createSupabaseClient> | undefined;

function getSupabaseClient() {
  if (!_supabase) {
    _supabase = createSupabaseClient();
    // The `accessToken` option above only covers REST/Storage — Realtime
    // keeps its own auth state and needs the token pushed explicitly via
    // realtime.setAuth() on every change, or channel subscriptions silently
    // authenticate once and then stop delivering postgres_changes events
    // once that token expires (confirmed live: a channel opened fine but
    // never received an UPDATE payload). onIdTokenChanged (not just
    // onAuthStateChanged) is required here too, since Firebase's hourly
    // background token refresh doesn't fire an auth-state event but still
    // invalidates whatever token Realtime was last given.
    if (typeof window !== 'undefined') {
      onIdTokenChanged(firebaseAuth, async (user) => {
        const token = (await user?.getIdToken()) ?? null;
        _supabase!.realtime.setAuth(token);
      });
    }
  }
  return _supabase;
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";
export const supabase = new Proxy({} as ReturnType<typeof createSupabaseClient>, {
  get(_, prop, receiver) {
    return Reflect.get(getSupabaseClient(), prop, receiver);
  },
});

